SELECT COUNT(*)
FROM ai_agent_persona
WHERE persona_source_id = #{personaId}

SELECT artifactPath
FROM (
    SELECT s.raw_artifact_path AS artifactPath
    FROM ai_persona_source s
    WHERE s.id = #{personaId} AND s.owner_user_id = #{userId}
    UNION
    SELECT v.source_artifact_path AS artifactPath
    FROM ai_persona_version v
    JOIN ai_persona_source s ON s.id = v.persona_source_id
    WHERE v.persona_source_id = #{personaId} AND s.owner_user_id = #{userId}
    UNION
    SELECT j.artifact_path AS artifactPath
    FROM ai_persona_import_job j
    WHERE j.owner_user_id = #{userId}
      AND (
          j.expected_persona_id = #{personaId}
          OR JSON_UNQUOTE(JSON_EXTRACT(j.compile_result_json, '$.personaId')) = #{personaId}
      )
) paths
WHERE artifactPath IS NOT NULL AND artifactPath != ''

