WHERE operator_user_id = #{userId}
  AND (
      target_id = #{personaId}
      OR target_id LIKE CONCAT(#{personaId}, '@%')
      OR target_id LIKE CONCAT(#{personaId}, '#%')
      OR JSON_SEARCH(details_json, 'one', #{personaId}) IS NOT NULL
  )

