mapper.update:
UPDATE ai_persona_signature_override
SET disabled = #{disabled}, updated_at = NOW()
WHERE persona_source_id = #{personaId}
  AND persona_version = #{version}
  AND signature_key = #{signatureKey}
  AND owner_user_id = #{ownerUserId}

UPDATE ai_persona_version v
JOIN ai_persona_source s ON s.id = v.persona_source_id
SET v.status = 'published',
    v.published_at = NOW(),
    v.published_by = #{userId}
WHERE v.persona_source_id = #{personaId}
  AND v.version = #{version}
  AND s.owner_user_id = #{userId}
  AND v.status = 'draft'
  AND JSON_UNQUOTE(JSON_EXTRACT(v.validation_report, '$.valid')) = 'true'
  AND v.test_status = 'passed'

UPDATE ai_persona_test_run
SET status = #{status}, score_json = #{scoreJson}, report_json = #{reportJson}
WHERE id = #{id}

UPDATE ai_persona_version
SET test_status = #{testStatus}, quality_score = #{qualityScore}, test_report = #{testReport}
WHERE persona_source_id = #{personaId} AND version = #{version}

